/*!
 * area-map runtime: selection logic for the SVG maps generated by
 * tools/geojson-to-svg.mjs.
 *
 * The generator embeds this file inside every SVG, so a map works on its own.
 * Include it in the host page as well (<script src="area-map.js"></script>)
 * when:
 *   - the SVG is inserted with innerHTML or by a framework (browsers do not
 *     run <script> tags inserted that way), or
 *   - the SVG is loaded with <object>/<iframe> and you want external
 *     checkboxes to stay in sync with it.
 *
 * Written in ES5 on purpose, so it runs in as many browsers and SVG viewers
 * as possible.
 *
 * ---------------------------------------------------------------------------
 * External checkboxes (no code needed)
 * ---------------------------------------------------------------------------
 *   <input type="checkbox" data-area-map="caba-barrios" value="palermo">
 *
 * Any checkbox (or radio button) whose data-area-map matches the map id
 * (the data-am-map attribute of the <svg>, set with --map-id) and whose value
 * is an area id stays in sync both ways: clicking the map checks the box, and
 * checking the box selects the area. Boxes that are already checked when the
 * page loads (e.g. a form restored by the browser) select their areas.
 *
 * ---------------------------------------------------------------------------
 * JavaScript API (property .areaMap of every <svg class="area-map">)
 * ---------------------------------------------------------------------------
 *   svg.areaMap.select(id[, true|false])  select or deselect an area
 *   svg.areaMap.toggle(id)                toggle an area
 *   svg.areaMap.clear()                   deselect everything
 *   svg.areaMap.selected()                selected ids (array)
 *   svg.areaMap.areas()                   [{id, name}] of every area
 *
 * Event "areachange" (bubbles), fired when the user changes the selection:
 *   event.detail = {map, id, name, selected, selection: [ids]}
 *
 * When the SVG is loaded with <object> or <iframe> it also tells the parent
 * page:
 *   postMessage({type: "area-map:change", map, id, name, selected, selection})
 * and accepts
 *   postMessage({type: "area-map:select", map, ids: [...]})
 * to replace the selection from outside.
 */
(function (global) {
  "use strict";

  var SVG_NS = "http://www.w3.org/2000/svg";
  var doc = global.document;
  if (!doc) return;

  function hasClass(el, name) {
    var c = el && el.getAttribute && el.getAttribute("class");
    return !!c && (" " + c + " ").indexOf(" " + name + " ") !== -1;
  }

  // Walks up from an event target to the area's <g class="am-hit">.
  // correspondingUseElement covers old browsers that report an
  // SVGElementInstance as the target inside a <use>.
  function findHit(node, root) {
    while (node && node !== root) {
      if (node.correspondingUseElement) node = node.correspondingUseElement;
      if (hasClass(node, "am-hit")) return node;
      node = node.parentNode;
    }
    return null;
  }

  function makeEvent(name, detail) {
    var ev;
    try {
      ev = new CustomEvent(name, { bubbles: true, detail: detail });
    } catch (e) {
      ev = doc.createEvent("CustomEvent");
      ev.initCustomEvent(name, true, false, detail);
    }
    return ev;
  }

  function isAreaInput(el) {
    return !!el && el.nodeName && el.nodeName.toLowerCase() === "input" &&
      (el.type === "checkbox" || el.type === "radio") && !!el.getAttribute("data-area-map");
  }

  // Inputs bound to a map, anywhere in the page.
  function inputsFor(mapId) {
    var out = [];
    var list = doc.getElementsByTagName("input");
    for (var i = 0; i < list.length; i++) {
      if (isAreaInput(list[i]) && list[i].getAttribute("data-area-map") === mapId) out.push(list[i]);
    }
    return out;
  }

  function syncInputs(mapId, selection) {
    var wanted = {};
    for (var i = 0; i < selection.length; i++) wanted[selection[i]] = true;
    var inputs = inputsFor(mapId);
    for (i = 0; i < inputs.length; i++) inputs[i].checked = !!wanted[inputs[i].value];
  }

  function checkedIds(mapId) {
    var out = [];
    var inputs = inputsFor(mapId);
    for (var i = 0; i < inputs.length; i++) if (inputs[i].checked) out.push(inputs[i].value);
    return out;
  }

  // Inline maps in this document, by map id.
  function inlineMaps(mapId) {
    var out = [];
    var list = doc.getElementsByTagNameNS(SVG_NS, "svg");
    for (var i = 0; i < list.length; i++) {
      if (list[i].areaMap && list[i].getAttribute("data-am-map") === mapId) out.push(list[i]);
    }
    return out;
  }

  // Maps loaded with <object>/<iframe>: messages go to every frame, and each
  // SVG ignores the ones addressed to other maps.
  function postToFrames(msg) {
    var frames = [];
    var tags = ["object", "iframe", "embed"];
    for (var t = 0; t < tags.length; t++) {
      var list = doc.getElementsByTagName(tags[t]);
      for (var i = 0; i < list.length; i++) frames.push(list[i]);
    }
    for (i = 0; i < frames.length; i++) {
      try {
        var win = frames[i].contentWindow ||
          (frames[i].getSVGDocument && frames[i].getSVGDocument().defaultView);
        if (win) win.postMessage(msg, "*");
      } catch (e) { /* frame not ready or not accessible */ }
    }
  }

  function init(svg) {
    if (!svg || svg.areaMap || !hasClass(svg, "area-map")) return svg && svg.areaMap;

    var single = svg.getAttribute("data-am-mode") === "single";
    var mapId = svg.getAttribute("data-am-map") || "";
    var standalone = svg === doc.documentElement;
    var hits = {};
    var parts = {};
    var order = [];
    var all = svg.getElementsByTagName("*");
    var i, el, id;

    // id -> elements that show the state of that area.
    for (i = 0; i < all.length; i++) {
      el = all[i];
      id = el.getAttribute("data-area");
      if (!id) continue;
      (parts[id] = parts[id] || []).push(el);
      if (hasClass(el, "am-hit")) {
        hits[id] = el;
        order.push(id);
      }
    }

    function isSelected(id) {
      return !!hits[id] && hits[id].getAttribute("aria-checked") === "true";
    }

    function paint(id, on) {
      var list = parts[id] || [];
      for (var j = 0; j < list.length; j++) {
        list[j].setAttribute("data-selected", on ? "true" : "false");
      }
      hits[id].setAttribute("aria-checked", on ? "true" : "false");
    }

    function selection() {
      var out = [];
      for (var j = 0; j < order.length; j++) if (isSelected(order[j])) out.push(order[j]);
      return out;
    }

    function nameOf(id) {
      return hits[id] ? hits[id].getAttribute("aria-label") : null;
    }

    function notify(id) {
      var sel = selection();
      var detail = { map: mapId, id: id, name: nameOf(id), selected: isSelected(id), selection: sel };
      if (!standalone) syncInputs(mapId, sel);
      svg.dispatchEvent(makeEvent("areachange", detail));
      if (standalone && global.parent && global.parent !== global) {
        try {
          global.parent.postMessage({
            type: "area-map:change", map: mapId, id: detail.id, name: detail.name,
            selected: detail.selected, selection: sel
          }, "*");
        } catch (e) { /* no reachable parent */ }
      }
    }

    function select(id, on, silent) {
      if (!hits[id]) return false;
      on = !!on;
      if (single && on) {
        for (var j = 0; j < order.length; j++) {
          if (order[j] !== id && isSelected(order[j])) paint(order[j], false);
        }
      }
      if (isSelected(id) === on) return true;
      paint(id, on);
      if (!silent) notify(id);
      else if (!standalone) syncInputs(mapId, selection());
      return true;
    }

    function setSelection(ids) {
      var wanted = {};
      for (var j = 0; j < ids.length; j++) wanted[ids[j]] = true;
      for (j = 0; j < order.length; j++) select(order[j], !!wanted[order[j]], true);
    }

    function toggle(id) {
      return select(id, !isSelected(id));
    }

    svg.addEventListener("click", function (e) {
      var hit = findHit(e.target, svg);
      if (hit) toggle(hit.getAttribute("data-area"));
    }, false);

    svg.addEventListener("keydown", function (e) {
      var key = e.key || e.keyCode;
      if (key !== "Enter" && key !== " " && key !== "Spacebar" && key !== 13 && key !== 32) return;
      var hit = findHit(e.target, svg);
      if (!hit) return;
      if (e.preventDefault) e.preventDefault();
      toggle(hit.getAttribute("data-area"));
    }, false);

    if (standalone && global.addEventListener) {
      global.addEventListener("message", function (e) {
        var msg = e.data;
        if (!msg || msg.type !== "area-map:select" || !msg.ids) return;
        if (msg.map && msg.map !== mapId) return;
        setSelection(msg.ids);
      }, false);
    }

    svg.areaMap = {
      select: function (id, on) { return select(id, on === undefined ? true : on); },
      toggle: toggle,
      clear: function () {
        for (var j = 0; j < order.length; j++) select(order[j], false);
      },
      selected: selection,
      areas: function () {
        var out = [];
        for (var j = 0; j < order.length; j++) out.push({ id: order[j], name: nameOf(order[j]) });
        return out;
      },
      // Internal: used by the checkbox binding.
      _set: setSelection
    };

    // Checkboxes already checked (e.g. restored by the browser) win.
    if (!standalone) {
      var pre = checkedIds(mapId);
      if (pre.length) setSelection(pre);
    }
    return svg.areaMap;
  }

  function initAll(root) {
    var list = (root || doc).getElementsByTagNameNS(SVG_NS, "svg");
    for (var i = 0; i < list.length; i++) init(list[i]);
  }

  // Initialize the <svg> that contains this script right away (the script is
  // the last child of the generated SVG, so every element already exists).
  var current = doc.currentScript;
  if (current && current.ownerSVGElement) init(current.ownerSVGElement);

  // The rest is set up once per page, even if this file runs several times
  // (one copy per inline map, plus maybe one in the host page).
  if (global.AreaMap) {
    global.AreaMap.initAll();
    return;
  }
  global.AreaMap = { init: init, initAll: initAll };

  if (doc.documentElement.namespaceURI !== SVG_NS) {
    // Host HTML page: keep bound inputs in sync with the maps.
    doc.addEventListener("change", function (e) {
      var input = e.target;
      if (!isAreaInput(input)) return;
      var mapId = input.getAttribute("data-area-map");
      var ids = checkedIds(mapId);
      var maps = inlineMaps(mapId);
      for (var i = 0; i < maps.length; i++) {
        if (input.type === "radio" || maps[i].getAttribute("data-am-mode") === "single") {
          maps[i].areaMap.select(input.value, input.checked);
        } else {
          maps[i].areaMap._set(ids);
        }
      }
      if (!maps.length) postToFrames({ type: "area-map:select", map: mapId, ids: ids });
    }, false);

    global.addEventListener("message", function (e) {
      var msg = e.data;
      if (msg && msg.type === "area-map:change" && msg.map && msg.selection) {
        syncInputs(msg.map, msg.selection);
      }
    }, false);
  }

  // Inline maps are initialized while the page is still being parsed, maybe
  // before their checkboxes exist. Once the DOM is ready, checked boxes win.
  function applyInputs() {
    var list = doc.getElementsByTagNameNS(SVG_NS, "svg");
    for (var i = 0; i < list.length; i++) {
      var svg = list[i];
      if (!svg.areaMap || svg === doc.documentElement) continue;
      var pre = checkedIds(svg.getAttribute("data-am-map") || "");
      if (pre.length) svg.areaMap._set(pre);
    }
  }

  if (doc.readyState === "loading" && doc.addEventListener) {
    doc.addEventListener("DOMContentLoaded", function () { initAll(); applyInputs(); }, false);
  } else {
    initAll();
  }
})(typeof window !== "undefined" ? window : this);
